function statusOf(msg) {
  return {
    title: msg.titleRaw || t(msg.titleKey, msg.titleVars),
    detail: msg.detailRaw || t(msg.detailKey, msg.detailVars),
    tone: msg.tone || '',
  };
}

function buildCells(options) {
  const values = options.values;
  const given = options.given || [];
  const notes = options.notes || EMPTY_NOTES();
  const candidates = options.candidates || null;
  const showAllCandidates = !!options.showAllCandidates;
  const showCandidatesFor = options.showCandidatesFor || null;
  const selected = typeof options.selected === 'number' ? options.selected : -1;
  const selectedValue = selected >= 0 ? values[selected] : 0;
  const peerSet = selected >= 0 ? new Set(core.PEERS[selected]) : new Set();
  const conflicts = options.conflicts || new Set();
  const wrong = options.wrong || new Set();
  const highlight = options.highlight || {};
  const primary = new Set(highlight.primary || []);
  const secondary = new Set(highlight.secondary || []);
  const unitCells = new Set();
  for (const unit of highlight.units || []) {
    if (core.UNITS[unit]) core.UNITS[unit].forEach((index) => unitCells.add(index));
  }
  const roleMap = new Map();
  for (const entry of highlight.candidates || []) {
    roleMap.set(entry.cell + ':' + entry.digit, entry.role || 'pattern');
  }
  const cells = [];
  for (let index = 0; index < 81; index++) {
    const r = core.rowOf(index);
    const c = core.colOf(index);
    const digit = values[index] || 0;
    let mask = 0;
    if (!digit) {
      if (showAllCandidates && candidates) mask = candidates[index] || 0;
      else if (showCandidatesFor && showCandidatesFor.has(index) && candidates) mask = candidates[index] || 0;
      else mask = notes[index] || 0;
    }
    const classes = ['cell'];
    if (given[index]) classes.push('given');
    if (selected === index) classes.push('selected');
    else if (peerSet.has(index)) classes.push('peer');
    if (selectedValue && digit === selectedValue) classes.push('same');
    if (conflicts.has(index)) classes.push('conflict');
    if (wrong.has(index)) classes.push('wrong');
    if (primary.has(index)) classes.push('hint-primary');
    if (secondary.has(index)) classes.push('hint-secondary');
    if (unitCells.has(index)) classes.push('unit-highlight');
    if (c === 2 || c === 5) classes.push('cell-br');
    if (r === 2 || r === 5) classes.push('cell-bb');
    if (c === 8) classes.push('cell-lc');
    if (r === 8) classes.push('cell-lr');
    const noteItems = [];
    for (let d = 1; d <= 9; d++) {
      let noteClass = 'note';
      if (!digit && (mask & bit(d))) {
        noteClass += ' on';
        const role = roleMap.get(index + ':' + d);
        if (role) noteClass += ' cand-' + role;
      }
      noteItems.push({ d, cls: noteClass });
    }
    cells.push({ index, value: digit ? String(digit) : '', cls: classes.join(' '), notes: noteItems });
  }
  return cells;
}

function numCounts(values) {
  const counts = new Array(10).fill(0);
  values.forEach((value) => { if (value) counts[value]++; });
  const out = [];
  for (let d = 1; d <= 9; d++) out.push({ digit: d, left: Math.max(0, 9 - counts[d]), done: counts[d] >= 9 });
  return out;
}

Page({
  data: {
    labels: {},
    tabs: [],
    activeTab: 'play',
    difficulties: [],
    boardSize: 324,
    cellSize: 36,
    valueFont: 20,
    noteFont: 8,
    play: {
      cells: [], numCounts: [], timeText: '00:00', filled: 0, notesCount: 0,
      clues: 0, difficultyLabel: '—', ratingLabel: '—', techniqueLabel: '—',
      notesMode: false, paused: false, finished: false,
      errorLabels: [], errorIndex: 0, targetDifficulty: 'easy',
      status: { title: '', detail: '', tone: '' }, hint: null,
    },
    con: {
      cells: [], numCounts: [], clues: 0, empty: 81, notesMode: false,
      status: { title: '', detail: '', tone: '' }, note: '—', startEnabled: false,
    },
    solver: {
      input: '', cells: [], warning: '', difficulty: '—', clues: '—',
      technique: '—', tier: '', explanation: '', counter: '', steps: [], counts: [],
      index: 0, max: 0, canPrev: false, canNext: false, autoplay: false,
      solvedChip: '', idle: true,
    },
    theme: 'light',
    themeIcon: '☾',
    languages: [],
    langIndex: 0,
    languageLabel: '',
    replay: {
      records: [], selectedId: '', diff: '—', operations: '—', duration: '—',
      counter: '', action: '', cells: [], index: 0, max: 0, canPrev: false, canNext: false,
      playing: false, empty: true,
    },
    stats: {
      total: 0, fastest: '—', average: '—', rows: [], recent: [], empty: true,
    },
    io: { visible: false, text: '', mode: 'play', error: '' },
    ocr: { visible: false, busy: false, error: '', errorKey: '', preview: '', status: '', progress: 0 },
    win: { visible: false, time: '', difficulty: '', rating: '' },
  },

  // ------------------------------------------------------------------------
  // Lifecycle
  // ------------------------------------------------------------------------
  onLoad() {
    this.initState();
    this.initLanguage();
    this.computeLayout();
    this.refreshLabels();
    this.timerInterval = setInterval(() => this.syncTime(), 500);
    this.applyNavTheme();
    this.setData({
      theme: this.theme,
      themeIcon: this.themeIcon,
      play: Object.assign({}, this.data.play, { status: statusOf(this.playMsg) }),
      con: Object.assign({}, this.data.con, { status: statusOf(this.conMsg) }),
    });
    this.syncConstructor();
    this.syncSolver();
    this.syncReplay();
    this.syncStats();
    this.newPuzzle();
  },

  onHide() {
    if (this.timerRunning) {
      this.pauseTimer();
      this.setData({ 'play.paused': true });
    }
    this.stopAutoplay();
  },

  onResize() {
    this.computeLayout();
  },

  onUnload() {
    if (this.timerInterval) clearInterval(this.timerInterval);
    this.stopAutoplay();
    if (this.conAnalysisTimer) clearTimeout(this.conAnalysisTimer);
  },

  initState() {
    this.play = {
      values: EMPTY_VALUES(), given: new Array(81).fill(false), notes: EMPTY_NOTES(),
      solution: null, meta: null, selected: -1, notesMode: false, errorMode: 'immediate',
      checked: false, finished: false, paused: false, hintStep: null,
      statsRecorded: false, finalTime: 0,
    };
    this.playHistory = [];
    this.playTargetDifficulty = 'easy';
    this.playMsg = { titleKey: 'play.loadingBoard', detailKey: 'play.generating.detail', tone: 'busy' };
    this.timerBase = 0;
    this.timerStartedAt = 0;
    this.timerRunning = false;
    this.generating = false;

    this.con = {
      values: EMPTY_VALUES(), notes: EMPTY_NOTES(), selected: 40, notesMode: false,
      analysis: null, timer: null,
    };
    this.conMsg = { titleKey: 'status.empty', detailKey: 'constructor.emptyHint', tone: '', note: '—' };

    this.solver = {
      trace: null, states: [], index: 0, given: [], sourcePuzzle: '',
      input: '', multiple: false, autoplay: false, timer: null,
    };

    this.ioText = '';
    this.ioMode = 'play';

    this.statsData = statsModel.normalize(this.readStore(STATS_KEY, null));
    this.replayCurrent = replayModel.normalizeRecording(this.readStore(REPLAY_CURRENT_KEY, null));
    this.replayHistory = (this.readStore(REPLAY_HISTORY_KEY, []) || [])
      .map((item) => replayModel.normalizeRecording(item))
      .filter(Boolean)
      .slice(0, MAX_REPLAY_HISTORY);
    this.replaySelection = null;
    this.replayView = { index: 0, playing: false, timer: null };
    const savedTheme = this.readStore(THEME_KEY, 'light');
    this.theme = THEMES.includes(savedTheme) ? savedTheme : 'light';
    this.themeIcon = { light: '☾', dark: '◑', eye: '☀' }[this.theme];
  },

  readStore(key, fallback) {
    try {
      const value = wx.getStorageSync(key);
      return value === '' || value === undefined || value === null ? fallback : value;
    } catch (error) { return fallback; }
  },

  writeStore(key, value) {
    try { wx.setStorageSync(key, value); } catch (error) { /* local storage may be full */ }
  },

  themeName(theme) {
    return t({ light: 'theme.light', dark: 'theme.dark', eye: 'theme.eye' }[theme] || 'theme.light');
  },

  applyNavTheme() {
    const color = this.theme === 'eye' ? '#f2f0e4' : this.theme === 'dark' ? '#151d24' : '#0f766e';
    try {
      wx.setNavigationBarColor({
        frontColor: this.theme === 'eye' ? '#000000' : '#ffffff',
        backgroundColor: color,
        animation: { duration: 180, timingFunc: 'easeIn' },
      });
    } catch (error) { /* older base library */ }
  },

  cycleTheme() {
    const next = THEMES[(THEMES.indexOf(this.theme) + 1) % THEMES.length];
    this.theme = next;
    this.themeIcon = { light: '☾', dark: '◑', eye: '☀' }[next];
    this.writeStore(THEME_KEY, next);
    this.setData({ theme: next, themeIcon: this.themeIcon });
    this.applyNavTheme();
    wx.showToast({ title: t('theme.switched', { name: this.themeName(next) }), icon: 'none' });
  },

  initLanguage() {
    let lang = null;
    try { lang = i18n.normalizeLanguage(wx.getStorageSync('sudoku.lang')); } catch (error) { /* ignore */ }
    if (!lang) {
      let system = '';
      try {
        const info = wx.getSystemInfoSync();
        system = info.language || '';
      } catch (error) { /* ignore */ }
      lang = i18n.normalizeLanguage(system) || 'en';
    }
    i18n.setLang(lang);
    try { wx.setNavigationBarTitle({ title: t('app.title') }); } catch (error) { /* ignore */ }
  },

  computeLayout() {
    let win = { windowWidth: 375 };
    try { win = wx.getWindowInfo ? wx.getWindowInfo() : wx.getSystemInfoSync(); } catch (error) { /* ignore */ }
    const width = Math.min(win.windowWidth - 32, 560);
    const cellSize = Math.floor(width / 9);
    this.setData({
      cellSize,
      boardSize: cellSize * 9,
      valueFont: Math.max(16, Math.floor(cellSize * 0.52)),
      noteFont: Math.max(7, Math.floor(cellSize * 0.21)),
    });
  },

  refreshLabels() {
    const labels = buildLabels();
    const tabs = [
      { key: 'play', label: labels.playTab },
      { key: 'constructor', label: labels.constructorTab },
      { key: 'solver', label: labels.solverTab },
      { key: 'replay', label: labels.replayTab },
      { key: 'stats', label: labels.statsTab },
    ];
    const difficulties = [
      { key: 'easy', label: t('play.difficulty.easy') },
      { key: 'medium', label: t('play.difficulty.medium') },
      { key: 'hard', label: t('play.difficulty.hard') },
    ];
    const errorLabels = [t('play.error.immediate'), t('play.error.check'), t('play.error.off')];
    const languages = i18n.languages();
    const langIndex = Math.max(0, i18n.LANGUAGES.indexOf(i18n.getLang()));
    this.setData({
      labels,
      tabs,
      difficulties,
      languages,
      langIndex,
      languageLabel: i18n.languageLabel(i18n.getLang()),
      play: Object.assign({}, this.data.play, { errorLabels }),
    });
  },

  onLanguageChange(event) {
    const index = Number(event.detail.value);
    const choice = this.data.languages[index];
    if (!choice) return;
    i18n.setLang(choice.code);
    this.writeStore('sudoku.lang', choice.code);
    try {
      wx.setNavigationBarTitle({ title: t('app.title') });
    } catch (error) { /* ignore */ }
    this.refreshLabels();
    this.syncPlay();
    this.syncConstructor();
    this.syncSolver();
    this.syncReplay();
    this.syncStats();
    this.setData({
      io: Object.assign({}, this.data.io, { error: '' }),
      ocr: Object.assign({}, this.data.ocr, {
        error: this.data.ocr.errorKey ? t(this.data.ocr.errorKey) : '',
      }),
      win: this.data.win.visible ? Object.assign({}, this.data.win, this.winLabels()) : this.data.win,
    });
  },

  switchTab(event) {
    const tab = event.currentTarget.dataset.tab;
    if (tab === this.data.activeTab) return;
    if (tab !== 'solver') this.stopAutoplay();
    if (tab !== 'replay') this.stopReplayPlayback();
    this.setData({ activeTab: tab });
    if (tab === 'constructor') this.syncConstructor();
    if (tab === 'solver') this.syncSolver();
    if (tab === 'play') this.syncPlay();
    if (tab === 'replay') this.syncReplay();
    if (tab === 'stats') this.syncStats();
  },

  noop() {},

  // ------------------------------------------------------------------------
  // Timer
  // ------------------------------------------------------------------------
  timerValue() {
    return this.timerBase + (this.timerRunning ? Date.now() - this.timerStartedAt : 0);
  },
  startTimer() {
    if (this.timerRunning) return;
    this.timerStartedAt = Date.now();
    this.timerRunning = true;
  },
  pauseTimer() {
    if (!this.timerRunning) return;
    this.timerBase += Date.now() - this.timerStartedAt;
    this.timerStartedAt = 0;
    this.timerRunning = false;
  },
  resetTimer(start) {
    this.timerBase = 0;
    this.timerStartedAt = 0;
    this.timerRunning = false;
    if (start) this.startTimer();
    this.syncTime();
  },
  syncTime() {
    this.setData({ 'play.timeText': formatTime(this.timerValue()) });
  },

  // ------------------------------------------------------------------------
  // Shared replay recording + local statistics
  // ------------------------------------------------------------------------
  persistReplayState() {
    this.writeStore(REPLAY_CURRENT_KEY, this.replayCurrent || null);
    this.writeStore(REPLAY_HISTORY_KEY, this.replayHistory);
  },

  persistStats() {
    this.writeStore(STATS_KEY, this.statsData);
  },

  startReplayRecording() {
    if (!this.play.meta) return;
    this.replayCurrent = replayModel.createRecording({
      puzzle: this.play.meta.puzzleString,
      solution: this.play.meta.solutionString,
      values: this.play.values,
      notes: this.play.notes,
      difficulty: this.play.meta.difficulty || 'easy',
      maxTier: this.play.meta.maxTier || 0,
      startedAt: Date.now(),
    });
    this.replaySelection = null;
    this.replayView.index = 0;
    this.persistReplayState();
  },

  archiveReplay(status, durationMs) {
    if (!this.replayCurrent) return;
    const ended = replayModel.markEnded(this.replayCurrent, status, durationMs);
    if (replayModel.actionCount(ended) > 0 || status === 'completed') {
      const clone = JSON.parse(JSON.stringify(ended));
      if (!this.replayHistory.some((item) => item.id === clone.id)) {
        this.replayHistory.unshift(clone);
        this.replayHistory = this.replayHistory.slice(0, MAX_REPLAY_HISTORY);
        if (this.replaySelection && this.replaySelection.id === clone.id) {
          this.replaySelection = clone;
          this.replayView.index = replayModel.actionCount(clone);
        }
      }
    }
    this.replayCurrent = null;
    this.persistReplayState();
    if (this.data.activeTab === 'replay') this.syncReplay();
  },

  logPlayAction(type, extra) {
    if (!this.replayCurrent) return;
    extra = extra || {};
    replayModel.recordAction(this.replayCurrent, {
      type,
      cell: extra.cell,
      digit: extra.digit,
      technique: extra.technique,
      durationMs: this.timerValue(),
      snapshot: { values: this.play.values, notes: this.play.notes },
    });
    this.persistReplayState();
  },

  recordCompletionStats() {
    if (this.play.statsRecorded) return;
    this.play.statsRecorded = true;
    this.statsData = statsModel.recordCompletion(this.statsData, {
      difficulty: (this.play.meta && this.play.meta.difficulty) || this.playTargetDifficulty || 'easy',
      timeMs: this.play.finalTime || this.timerValue(),
      completedAt: Date.now(),
    });
    this.persistStats();
  },

  replayRecords() {
    const list = [];
    if (this.replayCurrent) list.push({ record: this.replayCurrent, current: true });
    for (const record of this.replayHistory) list.push({ record, current: false });
    return list;
  },

  replayStatusLabel(record, current) {
    if (current || record.status === 'playing') return t('replay.status.playing');
    if (record.status === 'completed') return t('replay.status.completed');
    if (record.status === 'revealed') return t('replay.status.revealed');
    return t('replay.status.abandoned');
  },

  replayActionText(action) {
    if (!action) return t('replay.initial');
    const cell = action.cell === null || action.cell === undefined ? '—' : cellName(action.cell);
    if (action.type === 'value') return t('replay.action.value', { cell, digit: action.digit === null ? '—' : action.digit });
    if (action.type === 'erase') return t('replay.action.erase', { cell });
    if (action.type === 'notes') return t('replay.action.notes', { cell, digit: action.digit === null ? '—' : action.digit });
    if (action.type === 'undo') return t('replay.action.undo');
    if (action.type === 'hint') return t('replay.action.hint', { technique: action.technique ? i18n.techniqueName(action.technique) : '—' });
    if (action.type === 'reveal') return t('replay.action.reveal');
    return t('replay.action.unknown');
  },

  syncReplay() {
    const records = this.replayRecords();
    if (!this.replaySelection) {
      const playable = records.find((item) => replayModel.actionCount(item.record) > 0) || records[0] || null;
      this.replaySelection = playable ? playable.record : null;
      this.replayView.index = 0;
    }
    const list = records.map((item) => {
      const record = item.record;
      return {
        id: record.id,
        title: item.current ? t('replay.current') : this.replayStatusLabel(record, false),
        difficulty: i18n.difficultyName(record.difficulty),
        meta: t('replay.actionsCount', { n: replayModel.actionCount(record) }) + ' · ' +
          formatTime(item.current ? this.timerValue() : record.durationMs) + ' · ' + formatDate(record.startedAt),
        active: !!(this.replaySelection && this.replaySelection.id === record.id),
      };
    });
    const record = this.replaySelection;
    const empty = !record;
    const n = record ? replayModel.actionCount(record) : 0;
    this.replayView.index = record ? Math.max(0, Math.min(n, this.replayView.index)) : 0;
    const index = this.replayView.index;
    let given = new Array(81).fill(false);
    let snapshot = { values: EMPTY_VALUES(), notes: EMPTY_NOTES() };
    let action = null;
    if (record) {
      snapshot = replayModel.snapshotAt(record, index);
      try { given = core.parse(record.puzzle).map(Boolean); } catch (error) { /* ignore */ }
      action = index > 0 ? record.actions[index - 1] : null;
    }
    const cells = buildCells({
      values: snapshot.values,
      given,
      notes: snapshot.notes,
      selected: -1,
      conflicts: new Set(),
      wrong: new Set(),
      highlight: action && typeof action.cell === 'number' ? { primary: [action.cell] } : null,
    });
    this.setData({
      replay: {
        records: list,
        selectedId: record ? record.id : '',
        diff: record ? i18n.difficultyName(record.difficulty) : '—',
        operations: record ? String(n) : '—',
        duration: record ? formatTime(record === this.replayCurrent ? this.timerValue() : record.durationMs) : '—',
        counter: record ? t('replay.stepOf', { i: index, n }) : t('replay.noSelection'),
        action: record ? (index === 0 ? t('replay.initial') : this.replayActionText(action)) : t('replay.noSelection'),
        cells,
        index,
        max: n,
        canPrev: !!record && index > 0,
        canNext: !!record && index < n,
        playing: this.replayView.playing,
        empty,
      },
    });
  },

  stopReplayPlayback() {
    this.replayView.playing = false;
    if (this.replayView.timer) clearInterval(this.replayView.timer);
    this.replayView.timer = null;
    if (this.data.activeTab === 'replay') this.syncReplay();
  },

  toggleReplayPlayback() {
    if (!this.replaySelection) return;
    if (this.replayView.playing) {
      this.stopReplayPlayback();
      return;
    }
    const n = replayModel.actionCount(this.replaySelection);
    if (!n) return;
    if (this.replayView.index >= n) this.replayView.index = 0;
    this.replayView.playing = true;
    this.syncReplay();
    this.replayView.timer = setInterval(() => {
      const max = replayModel.actionCount(this.replaySelection);
      if (this.replayView.index >= max) {
        this.stopReplayPlayback();
        return;
      }
      this.replayView.index++;
      this.syncReplay();
      if (this.replayView.index >= max) this.stopReplayPlayback();
    }, 800);
  },

  selectReplay(event) {
    const id = event.currentTarget.dataset.id;
    const found = this.replayRecords().find((item) => item.record.id === id);
    if (!found) return;
    this.stopReplayPlayback();
    this.replaySelection = found.record;
    this.replayView.index = 0;
    this.syncReplay();
  },

  replayPrev() {
    if (!this.replaySelection) return;
    this.stopReplayPlayback();
    this.replayView.index = Math.max(0, this.replayView.index - 1);
    this.syncReplay();
  },

  replayNext() {
    if (!this.replaySelection) return;
    this.stopReplayPlayback();
    const max = replayModel.actionCount(this.replaySelection);
    this.replayView.index = Math.min(max, this.replayView.index + 1);
    this.syncReplay();
  },

  onReplaySlider(event) {
    if (!this.replaySelection) return;
    this.stopReplayPlayback();
    const max = replayModel.actionCount(this.replaySelection);
    this.replayView.index = Math.max(0, Math.min(max, Number(event.detail.value)));
    this.syncReplay();
  },

  syncStats() {
    const summary = statsModel.summary(this.statsData);
    const rows = statsModel.DIFFICULTIES.map((difficulty) => {
      const item = summary.byDifficulty[difficulty];
      return {
        key: difficulty,
        label: i18n.difficultyName(difficulty),
        count: t('stats.count', { n: item.completed }),
        detail: item.completed ? t('stats.best', { time: formatTime(item.bestMs) }) + ' · ' + t('stats.avg', { time: formatTime(item.averageMs) }) : '',
      };
    });
    const recent = summary.recent.map((item, index) => ({
      id: item.completedAt + '-' + index,
      difficulty: i18n.difficultyName(item.difficulty),
      time: formatTime(item.timeMs),
      date: formatDate(item.completedAt),
    }));
    this.setData({
      stats: {
        total: summary.completed,
        fastest: summary.bestMs === null ? '—' : formatTime(summary.bestMs),
        average: summary.averageMs === null ? '—' : formatTime(summary.averageMs),
        rows,
        recent,
        empty: summary.recent.length === 0,
      },
    });
  },

  resetStats() {
    wx.showModal({
      title: t('stats.reset'),
      content: t('stats.confirmReset'),
      confirmText: t('stats.reset'),
      cancelText: t('common.cancel'),
      success: (result) => {
        if (!result.confirm) return;
        this.statsData = statsModel.emptyStats();
        this.persistStats();
        this.syncStats();
        wx.showToast({ title: t('stats.resetDone'), icon: 'none' });
      },
    });
  },

  // ------------------------------------------------------------------------
  // Play
  // ------------------------------------------------------------------------
  setPlayMsg(titleKey, detailKey, tone, titleVars, detailVars) {
    this.playMsg = { titleKey, detailKey, tone, titleVars, detailVars };
  },

  renderPlayMsg() {
    const msg = this.playMsg;
    let titleVars = msg.titleVars;
    if (msg.titleKey === 'play.ready' && this.play.meta) {
      titleVars = {
        difficulty: i18n.difficultyName(this.play.meta.difficulty || 'easy'),
        clues: this.play.meta.clueCount,
      };
    } else if (msg.titleKey === 'play.win' && this.play.meta) {
      titleVars = {
        time: this.data.play.timeText,
        difficulty: i18n.difficultyName(this.play.meta.difficulty || 'easy'),
      };
    }
    return statusOf({ titleKey: msg.titleKey, detailKey: msg.detailKey, tone: msg.tone, titleVars, detailVars: msg.detailVars });
  },

  playMarks() {
    const conflicts = new Set();
    const wrong = new Set();
    if (!this.play.finished || this.play.checked) {
      if (this.play.errorMode !== 'off' || this.play.checked) {
        core.conflicts(this.play.values).forEach((cell) => conflicts.add(cell));
      }
      if (this.play.solution && (this.play.errorMode === 'immediate' || this.play.checked)) {
        for (let i = 0; i < 81; i++) {
          if (this.play.values[i] && !this.play.given[i] && this.play.values[i] !== this.play.solution[i]) wrong.add(i);
        }
      }
    }
    return { conflicts, wrong };
  },

  syncPlay() {
    const marks = this.playMarks();
    const hint = this.play.hintStep;
    let candidates = null;
    let showFor = null;
    if (hint) {
      candidates = core.candidates(this.play.values);
      showFor = new Set(hint.highlights.cells || []);
      for (const item of hint.eliminations || []) showFor.add(item.cell);
    }
    const cells = buildCells({
      values: this.play.values,
      given: this.play.given,
      notes: this.play.notes,
      candidates,
      showCandidatesFor: showFor,
      selected: this.play.selected,
      conflicts: marks.conflicts,
      wrong: marks.wrong,
      highlight: hint ? hint.highlights : null,
    });
    const meta = this.play.meta || {};
    const filled = this.play.values.filter(Boolean).length;
    const errorIndex = ['immediate', 'check', 'off'].indexOf(this.play.errorMode);
    this.setData({
      play: Object.assign({}, this.data.play, {
        cells,
        numCounts: numCounts(this.play.values),
        timeText: formatTime(this.timerValue()),
        filled,
        notesCount: this.play.notes.filter(Boolean).length,
        clues: meta.clueCount || this.play.values.filter(Boolean).length,
        difficultyLabel: meta.difficulty ? i18n.difficultyName(meta.difficulty) : '—',
        ratingLabel: meta.maxTier ? i18n.tierName(meta.maxTier) : '—',
        techniqueLabel: meta.technique ? i18n.techniqueName(meta.technique) : '—',
        notesMode: this.play.notesMode,
        paused: this.play.paused,
        finished: this.play.finished,
        errorIndex: Math.max(0, errorIndex),
        targetDifficulty: this.playTargetDifficulty,
        status: this.renderPlayMsg(),
        hint: hint ? {
          visible: true,
          technique: i18n.techniqueName(hint.technique),
          tier: t('tier.' + hint.tier),
          text: i18n.explain(hint),
        } : null,
      }),
    });
  },

  setDifficulty(event) {
    const difficulty = event.currentTarget.dataset.difficulty;
    this.playTargetDifficulty = difficulty;
    this.setPlayMsg('play.difficulty', 'play.difficulty.' + difficulty + '.desc', 'neutral');
    this.syncPlay();
  },

  onBoardTap(event) {
    const index = Number(event.currentTarget.dataset.index);
    if (this.data.activeTab === 'constructor') {
      this.con.selected = index;
      this.syncConstructor();
    } else if (this.data.activeTab === 'play') {
      if (this.generating) return;
      this.play.selected = index;
      this.playMsg = Object.assign({}, this.playMsg, {
        detailKey: 'play.selected',
        detailVars: { cell: cellName(index) },
      });
      this.syncPlay();
    }
  },

  pushPlayHistory() {
    this.playHistory.push({
      values: this.play.values.slice(),
      notes: this.play.notes.slice(),
      checked: this.play.checked,
    });
    if (this.playHistory.length > 200) this.playHistory.shift();
  },

  onPadTap(event) {
    this.playDigit(Number(event.currentTarget.dataset.digit));
  },

  playDigit(digit) {
    if (this.generating || this.play.finished) return;
    const index = this.play.selected;
    if (index < 0) {
      this.setPlayMsg('play.empty', 'play.empty', 'neutral');
      this.syncPlay();
      return;
    }
    if (this.play.given[index]) {
      this.setPlayMsg('play.inProgress', 'play.selected', 'neutral', null, { cell: cellName(index) });
      this.syncPlay();
      return;
    }
    if (this.play.notesMode && this.play.values[index]) return;
    this.pushPlayHistory();
    let actionType;
    let actionDigit = digit;
    if (this.play.notesMode) {
      this.play.notes[index] ^= bit(digit);
      actionType = 'notes';
    } else if (this.play.values[index] === digit) {
      this.play.values[index] = 0;
      actionType = 'erase';
      actionDigit = null;
    } else {
      this.play.values[index] = digit;
      this.play.notes[index] = 0;
      for (const peer of core.PEERS[index]) this.play.notes[peer] &= ~bit(digit);
      actionType = 'value';
    }
    this.play.checked = false;
    this.play.hintStep = null;
    this.logPlayAction(actionType, { cell: index, digit: actionDigit });
    this.afterPlayEdit();
  },

  erasePlay() {
    if (this.generating || this.play.finished) return;
    const index = this.play.selected;
    if (index < 0 || this.play.given[index]) return;
    if (!this.play.values[index] && !this.play.notes[index]) return;
    this.pushPlayHistory();
    this.play.values[index] = 0;
    this.play.notes[index] = 0;
    this.play.checked = false;
    this.play.hintStep = null;
    this.logPlayAction('erase', { cell: index });
    this.afterPlayEdit();
  },

  afterPlayEdit() {
    if (this.checkWin()) return;
    const marks = this.playMarks();
    if (marks.conflicts.size) this.setPlayMsg('play.conflict', 'play.empty', 'bad');
    else if (marks.wrong.size) this.setPlayMsg('play.wrongImmediate', 'play.empty', 'bad');
    else if (this.play.selected >= 0) {
      this.setPlayMsg('play.inProgress', 'play.selected', 'ok', null, { cell: cellName(this.play.selected) });
    }
    this.syncPlay();
  },

  checkWin() {
    if (this.play.finished) return true;
    if (!core.isSolved(this.play.values)) return false;
    this.play.finished = true;
    this.play.checked = false;
    this.play.paused = false;
    this.pauseTimer();
    this.play.finalTime = this.timerValue();
    this.recordCompletionStats();
    this.archiveReplay('completed', this.play.finalTime);
    this.syncStats();
    this.setPlayMsg('play.win', 'play.win.subtitle', 'ok', {
      time: formatTime(this.timerValue()),
      difficulty: i18n.difficultyName(this.play.meta && this.play.meta.difficulty || 'easy'),
    });
    this.syncPlay();
    this.setData({ win: Object.assign({ visible: true }, this.winLabels()) });
    return true;
  },

  winLabels() {
    return {
      visible: true,
      time: formatTime(this.timerValue()),
      difficulty: this.play.meta && this.play.meta.difficulty ? i18n.difficultyName(this.play.meta.difficulty) : '—',
      rating: this.play.meta && this.play.meta.maxTier ? i18n.tierName(this.play.meta.maxTier) : '—',
    };
  },

  closeWin() {
    this.setData({ win: Object.assign({}, this.data.win, { visible: false }) });
  },

  winNew() {
    this.closeWin();
    this.newPuzzle();
  },

  onUndo() {
    if (!this.playHistory.length || this.play.finished) {
      wx.showToast({ title: t('play.undo.empty'), icon: 'none' });
      return;
    }
    const previous = this.playHistory.pop();
    this.play.values = previous.values;
    this.play.notes = previous.notes;
    this.play.checked = previous.checked;
    this.play.hintStep = null;
    this.logPlayAction('undo', {});
    this.setPlayMsg('play.inProgress', 'play.empty', 'ok');
    this.syncPlay();
  },

  onHint() {
    if (this.generating || this.play.finished) return;
    const marks = this.playMarks();
    if (marks.conflicts.size) {
      this.setPlayMsg('play.conflict', 'play.empty', 'bad');
      this.syncPlay();
      return;
    }
    if (marks.wrong.size) {
      this.setPlayMsg('play.wrongImmediate', 'play.empty', 'bad');
      this.syncPlay();
      return;
    }
    const cands = core.candidates(this.play.values);
    const step = engine.findNextStep(this.play.values, cands, { assumeUnique: true });
    if (!step) {
      this.setPlayMsg('play.hint.none', 'play.empty', 'warn');
      this.syncPlay();
      return;
    }
    this.play.hintStep = step;
    this.setPlayMsg('play.hint.applied', 'play.empty', 'neutral', { technique: i18n.techniqueName(step.technique) });
    this.syncPlay();
  },

  closeHint() {
    this.play.hintStep = null;
    this.setPlayMsg('play.inProgress', 'play.empty', 'ok');
    this.syncPlay();
  },

  applyHint() {
    if (!this.play.hintStep || this.play.finished) return;
    this.pushPlayHistory();
    const step = this.play.hintStep;
    for (const placement of step.placements || []) {
      this.play.values[placement.cell] = placement.digit;
      this.play.notes[placement.cell] = 0;
      for (const peer of core.PEERS[placement.cell]) this.play.notes[peer] &= ~bit(placement.digit);
    }
    for (const elimination of step.eliminations || []) {
      this.play.notes[elimination.cell] &= ~bit(elimination.digit);
    }
    this.play.hintStep = null;
    this.play.checked = false;
    this.logPlayAction('hint', { technique: step.technique });
    if (!this.checkWin()) {
      this.setPlayMsg('play.hint.applied', 'play.empty', 'ok', { technique: i18n.techniqueName(step.technique) });
      this.syncPlay();
    }
  },

  onCheck() {
    if (this.generating) return;
    this.play.checked = true;
    if (this.checkWin()) return;
    const marks = this.playMarks();
    if (marks.wrong.size) this.setPlayMsg('play.check.wrong', 'play.empty', 'bad', { n: marks.wrong.size });
    else if (marks.conflicts.size) this.setPlayMsg('play.conflict', 'play.empty', 'bad');
    else this.setPlayMsg('play.check.ok', 'play.check.incomplete', 'ok', null, { status: t('play.check.valid') });
    this.syncPlay();
  },

  onReveal() {
    if (this.generating || !this.play.solution) return;
    wx.showModal({
      title: t('play.reveal'),
      content: t('play.confirm.reveal'),
      confirmText: t('play.reveal'),
      cancelText: t('common.cancel'),
      success: (result) => {
        if (!result.confirm) return;
        this.pauseTimer();
        this.play.values = this.play.solution.slice();
        this.play.notes = EMPTY_NOTES();
        this.play.hintStep = null;
        this.play.checked = false;
        this.play.finished = true;
        this.play.paused = false;
        this.play.finalTime = this.timerValue();
        this.logPlayAction('reveal', {});
        this.archiveReplay('revealed', this.play.finalTime);
        this.setPlayMsg('play.revealed', 'play.empty', 'neutral');
        this.syncPlay();
      },
    });
  },

  onRestart() {
    if (!this.play.meta || this.generating) return;
    wx.showModal({
      title: t('play.restart'),
      content: t('play.confirm.restart'),
      confirmText: t('play.restart'),
      cancelText: t('common.cancel'),
      success: (result) => {
        if (!result.confirm) return;
        this.archiveReplay('abandoned', this.timerValue());
        this.play.values = this.play.meta.originalValues.slice();
        this.play.given = this.play.values.map(Boolean);
        this.play.notes = EMPTY_NOTES();
        this.play.checked = false;
        this.play.finished = false;
        this.play.paused = false;
        this.play.hintStep = null;
        this.play.statsRecorded = false;
        this.play.finalTime = 0;
        this.playHistory = [];
        this.play.selected = this.play.values.findIndex((value) => !value);
        this.resetTimer(true);
        this.startReplayRecording();
        this.setPlayMsg('play.inProgress', 'play.empty', 'ok');
        this.syncPlay();
        this.syncStats();
        if (this.data.activeTab === 'replay') this.syncReplay();
      },
    });
  },

  onPause() {
    if (this.play.finished) return;
    this.play.paused = !this.play.paused;
    if (this.play.paused) {
      this.pauseTimer();
      this.setPlayMsg('play.paused', 'play.empty', 'neutral');
    } else {
      this.startTimer();
      this.setPlayMsg('play.inProgress', 'play.empty', 'ok');
    }
    this.syncPlay();
  },

  toggleNotes() {
    this.play.notesMode = !this.play.notesMode;
    this.setPlayMsg(this.play.notesMode ? 'play.candidatesOn' : 'play.candidatesOff', 'play.empty', 'neutral');
    this.syncPlay();
  },

  onErrorMode(event) {
    const modes = ['immediate', 'check', 'off'];
    this.play.errorMode = modes[Number(event.detail.value)] || 'immediate';
    this.play.checked = false;
    this.syncPlay();
  },

  newPuzzle() {
    if (this.generating) return;
    this.generating = true;
    this.play.hintStep = null;
    this.setPlayMsg('play.generating', 'play.generating.detail', 'busy');
    this.syncPlay();
    wx.showLoading({ title: t('play.generating'), mask: true });
    setTimeout(() => {
      let result;
      try {
        result = generator.generatePuzzle({ difficulty: this.playTargetDifficulty, timeLimitMs: 15000, maxAttempts: 900 });
      } catch (error) {
        result = { ok: false };
      }
      this.generating = false;
      wx.hideLoading();
      if (!result || !result.ok) {
        this.setPlayMsg('play.generate.failed', 'play.empty', 'bad');
        this.syncPlay();
        wx.showToast({ title: t('play.generate.failed'), icon: 'none' });
        return;
      }
      const meta = {
        difficulty: result.difficulty,
        maxTier: result.rating.maxTier,
        technique: hardestTechnique(result.rating),
        clueCount: result.clueCount,
        source: 'generated',
      };
      this.loadGame(result.puzzle, result.solution, meta);
    }, 40);
  },

  loadGame(puzzleString, solutionString, meta, notes) {
    this.archiveReplay('abandoned', this.timerValue());
    const values = core.parse(puzzleString);
    const solution = core.parse(solutionString);
    if (!meta.difficulty) meta.difficulty = this.playTargetDifficulty || 'easy';
    this.play.values = values.slice();
    this.play.given = values.map(Boolean);
    this.play.notes = notes ? notes.slice() : EMPTY_NOTES();
    this.play.solution = solution;
    this.play.selected = values.findIndex((value) => !value);
    if (this.play.selected < 0) this.play.selected = 0;
    this.play.checked = false;
    this.play.finished = false;
    this.play.paused = false;
    this.play.hintStep = null;
    this.playHistory = [];
    this.play.statsRecorded = false;
    this.play.finalTime = 0;
    if (meta.difficulty) this.playTargetDifficulty = meta.difficulty;
    this.play.meta = Object.assign({}, meta, {
      originalValues: values.slice(),
      clueCount: values.filter(Boolean).length,
      puzzleString: core.toPuzzleString(values),
      solutionString: core.toPuzzleString(solution),
    });
    this.resetTimer(true);
    this.startReplayRecording();
    this.setPlayMsg('play.ready', 'play.empty', 'ok', {
      difficulty: i18n.difficultyName(meta.difficulty || 'easy'),
      clues: this.play.meta.clueCount,
    });
    this.syncPlay();
    this.syncStats();
    this.setData({ win: Object.assign({}, this.data.win, { visible: false }) });
  },

  // ------------------------------------------------------------------------
  // Constructor
  // ------------------------------------------------------------------------
  setConMsg(titleKey, detailKey, tone, vars, detailVars, note) {
    this.conMsg = { titleKey, detailKey, tone, titleVars: vars, detailVars, note };
  },

  syncConstructor() {
    const conflicts = this.con.analysis && this.con.analysis.conflicts ? this.con.analysis.conflicts : [];
    const cells = buildCells({
      values: this.con.values,
      given: this.con.values.map(Boolean),
      notes: this.con.notes,
      selected: this.con.selected,
      conflicts: new Set(conflicts),
      wrong: new Set(),
      highlight: null,
    });
    let note = this.conMsg.note || '—';
    if (this.con.analysis && this.con.analysis.status === 'unique' && this.con.analysis.rating) {
      const rating = this.con.analysis.rating;
      note = rating.difficulty
        ? i18n.difficultyName(rating.difficulty) + ' · ' + (rating.maxTier ? i18n.tierName(rating.maxTier) : '—')
        : t('status.unique');
    }
    const status = statusOf(this.conMsg);
    this.setData({
      con: {
        cells,
        numCounts: numCounts(this.con.values),
        clues: this.con.values.filter(Boolean).length,
        empty: this.con.values.filter((value) => !value).length,
        notesMode: this.con.notesMode,
        status,
        note,
        startEnabled: !!(this.con.analysis && this.con.analysis.status === 'unique'),
      },
    });
  },

  selectConCell(event) {
    this.con.selected = Number(event.currentTarget.dataset.index);
    this.syncConstructor();
  },

  onConPad(event) {
    this.conDigit(Number(event.currentTarget.dataset.digit));
  },

  conDigit(digit) {
    const index = this.con.selected;
    if (index < 0) return;
    if (this.con.notesMode && this.con.values[index]) return;
    if (this.con.notesMode) {
      this.con.notes[index] ^= bit(digit);
    } else if (this.con.values[index] === digit) {
      this.con.values[index] = 0;
    } else {
      this.con.values[index] = digit;
      this.con.notes[index] = 0;
      for (const peer of core.PEERS[index]) this.con.notes[peer] &= ~bit(digit);
    }
    this.con.analysis = null;
    this.scheduleConAnalysis();
  },

  eraseCon() {
    const index = this.con.selected;
    if (index < 0) return;
    if (!this.con.values[index] && !this.con.notes[index]) return;
    this.con.values[index] = 0;
    this.con.notes[index] = 0;
    this.con.analysis = null;
    this.scheduleConAnalysis();
  },

  toggleConNotes() {
    this.con.notesMode = !this.con.notesMode;
    this.syncConstructor();
  },

  scheduleConAnalysis() {
    if (this.conAnalysisTimer) clearTimeout(this.conAnalysisTimer);
    this.syncConstructor();
    if (this.con.values.every((value) => !value)) {
      this.con.analysis = null;
      this.setConMsg('status.empty', 'constructor.emptyHint', '', null, null, '—');
      this.syncConstructor();
      return;
    }
    this.setConMsg('common.loading', 'constructor.subtitle', 'busy', null, null, '—');
    this.syncConstructor();
    this.conAnalysisTimer = setTimeout(() => this.analyzeCon(), 140);
  },

  analyzeCon() {
    const result = constructor.analyze(this.con.values);
    this.con.analysis = result;
    let note = '—';
    if (result.status === 'unique') {
      try {
        result.rating = engine.solveHuman(this.con.values);
        const rating = result.rating;
        note = rating.difficulty
          ? i18n.difficultyName(rating.difficulty) + ' · ' + (rating.maxTier ? i18n.tierName(rating.maxTier) : '—')
          : t('status.unique');
      } catch (error) { /* ignore */ }
    }
    if (result.status === 'unique') this.setConMsg('status.unique', 'constructor.uniqueHint', 'ok', null, null, note);
    else if (result.status === 'multiple') this.setConMsg('status.multiple', 'constructor.multipleHint', 'warn', null, null, note);
    else if (result.status === 'none') this.setConMsg('status.none', 'constructor.noneHint', 'bad', null, null, note);
    else if (result.status === 'conflict') {
      const names = (result.conflicts || []).slice(0, 7).map(cellName).join(i18n.listSeparator());
      this.setConMsg('status.conflict', 'constructor.conflictHint', 'bad', null, { cells: names || '—' }, note);
    } else this.setConMsg('status.invalid', 'constructor.invalidHint', 'bad', null, null, note);
    this.syncConstructor();
  },

  conClear() {
    this.con.values = EMPTY_VALUES();
    this.con.notes = EMPTY_NOTES();
    this.con.analysis = null;
    this.con.selected = 40;
    if (this.conAnalysisTimer) clearTimeout(this.conAnalysisTimer);
    this.setConMsg('status.empty', 'constructor.emptyHint', '', null, null, '—');
    this.syncConstructor();
  },

  conExample() {
    this.con.values = core.parse(CONSTRUCTOR_EXAMPLE);
    this.con.notes = EMPTY_NOTES();
    this.con.analysis = null;
    this.con.selected = this.con.values.findIndex((value) => !value);
    this.scheduleConAnalysis();
  },

  conStart() {
    if (!this.con.analysis || this.con.analysis.status !== 'unique') return;
    const result = constructor.analyze(this.con.values, { rate: true });
    if (result.status !== 'unique') return;
    const meta = {
      difficulty: result.rating ? result.rating.difficulty : null,
      maxTier: result.rating ? result.rating.maxTier : 0,
      technique: hardestTechnique(result.rating),
      clueCount: this.con.values.filter(Boolean).length,
      source: 'constructor',
    };
    this.loadGame(core.toPuzzleString(this.con.values), core.toPuzzleString(result.solution), meta, this.con.notes);
    this.setData({ activeTab: 'play' });
    wx.showToast({ title: t('play.ready', { difficulty: i18n.difficultyName(meta.difficulty || 'easy'), clues: meta.clueCount }), icon: 'none' });
  },

  // ------------------------------------------------------------------------
  // Solver
  // ------------------------------------------------------------------------
  setSolverInput(event) {
    this.solver.input = event.detail.value;
    this.setData({ 'solver.input': event.detail.value });
  },

  solverLoadCurrent() {
    if (this.play.meta && this.play.meta.puzzleString) {
      this.solver.input = this.play.meta.puzzleString;
      this.setData({ 'solver.input': this.solver.input });
      wx.showToast({ title: t('solver.loadCurrent'), icon: 'none' });
    } else {
      wx.showToast({ title: t('solver.needPuzzle'), icon: 'none' });
    }
  },

  solverLoadExample() {
    this.solver.input = EXAMPLE_PUZZLE;
    this.setData({ 'solver.input': this.solver.input });
    this.startSolver();
  },

  startSolver() {
    this.stopAutoplay();
    let source = (this.solver.input || '').trim();
    if (!source) {
      source = this.play.meta && this.play.meta.puzzleString ? this.play.meta.puzzleString : EXAMPLE_PUZZLE;
      this.solver.input = source;
    }
    this.solver.input = source;
    this.setData({ 'solver.input': source });
    const analysis = constructor.analyze(source);
    if (analysis.status === 'invalid' || analysis.status === 'conflict') {
      this.solver.trace = null;
      this.solver.warningKey = analysis.status === 'conflict' ? 'play.import.conflict' : 'solver.invalid';
      this.solver.warningVars = null;
      this.syncSolver();
      return;
    }
    if (analysis.status === 'none') {
      this.solver.trace = null;
      this.solver.warningKey = 'solver.none';
      this.solver.warningVars = null;
      this.syncSolver();
      return;
    }
    const trace = engine.solveHuman(source, { assumeUnique: analysis.status === 'unique' });
    if (trace.error) {
      this.solver.trace = null;
      this.solver.warningKey = 'solver.error';
      this.solver.warningVars = { error: trace.error };
      this.syncSolver();
      return;
    }
    const parsed = core.parse(source);
    this.solver.trace = trace;
    this.solver.sourcePuzzle = core.toPuzzleString(parsed);
    this.solver.given = parsed.map(Boolean);
    this.solver.index = 0;
    this.solver.multiple = analysis.status === 'multiple';
    this.solver.warningKey = this.solver.multiple ? 'solver.multiple' : null;
    this.solver.warningVars = null;
    this.solver.states = [{
      values: Array.from(trace.initial.values),
      candidates: Uint16Array.from(trace.initial.candidates),
    }];
    for (const step of trace.steps) {
      const previous = this.solver.states[this.solver.states.length - 1];
      const applied = engine.applyStep(previous.values, previous.candidates, step);
      this.solver.states.push({ values: applied.values, candidates: applied.candidates });
    }
    this.solver.index = 0;
    this.syncSolver();
  },

  solverStep(delta) {
    if (!this.solver.trace) return;
    this.stopAutoplay();
    const n = this.solver.trace.steps.length;
    this.solver.index = Math.max(0, Math.min(n, this.solver.index + delta));
    this.syncSolver();
  },

  solverPrev() { this.solverStep(-1); },
  solverNext() { this.solverStep(1); },

  solverSlider(event) {
    if (!this.solver.trace) return;
    this.stopAutoplay();
    this.solver.index = Number(event.detail.value);
    this.syncSolver();
  },

  solverStepTap(event) {
    if (!this.solver.trace) return;
    this.stopAutoplay();
    this.solver.index = Number(event.currentTarget.dataset.index);
    this.syncSolver();
  },

  toggleAutoplay() {
    if (!this.solver.trace) return;
    if (this.solver.autoplay) {
      this.stopAutoplay();
      return;
    }
    const n = this.solver.trace.steps.length;
    if (!n) return;
    if (this.solver.index >= n) this.solver.index = 0;
    this.solver.autoplay = true;
    this.solver.timer = setInterval(() => {
      const max = this.solver.trace.steps.length;
      if (this.solver.index >= max) {
        this.stopAutoplay();
        return;
      }
      this.solver.index++;
      this.syncSolver();
      if (this.solver.index >= max) this.stopAutoplay();
    }, 1150);
    this.syncSolver();
  },

  stopAutoplay() {
    this.solver.autoplay = false;
    if (this.solver.timer) clearInterval(this.solver.timer);
    this.solver.timer = null;
    if (this.data.activeTab === 'solver' && this.solver.trace) this.syncSolver();
  },

  syncSolver() {
    const trace = this.solver.trace;
    if (!trace) {
      this.setData({
        solver: Object.assign({}, this.data.solver, {
          cells: [],
          warning: this.solver.warningKey ? t(this.solver.warningKey, this.solver.warningVars) : '',
          idle: true,
          autoplay: false,
        }),
      });
      return;
    }
    const n = trace.steps.length;
    const index = Math.max(0, Math.min(n, this.solver.index));
    const atFinal = index >= n;
    const state = this.solver.states[index] || this.solver.states[0];
    const step = atFinal ? null : trace.steps[index];
    let highlight = step ? step.highlights : null;
    const cells = buildCells({
      values: Array.from(state.values),
      given: this.solver.given,
      notes: EMPTY_NOTES(),
      candidates: state.candidates,
      showAllCandidates: true,
      selected: -1,
      highlight,
    });
    const counts = [];
    for (const id of engine.techniqueIds) {
      const count = trace.counts[id] || 0;
      if (count) counts.push({ id, name: i18n.techniqueName(id), count });
    }
    const steps = trace.steps.map((item, i) => ({
      index: i,
      no: i + 1,
      name: i18n.techniqueName(item.technique),
      tier: t('tier.' + item.tier),
      active: index === i,
    }));
    steps.push({
      index: n,
      no: '✓',
      name: t('solver.final'),
      tier: '',
      active: index === n,
    });
    let technique = '—';
    let tier = '';
    let explanation = '';
    if (step) {
      technique = i18n.techniqueName(step.technique);
      tier = t('tier.' + step.tier);
      explanation = i18n.explain(step);
    } else if (trace.solved) {
      technique = t('solver.final');
      explanation = t('solver.solved', { n });
    } else {
      technique = t('solver.stalled');
      explanation = t('solver.stalled');
    }
    this.setData({
      solver: Object.assign({}, this.data.solver, {
        input: this.solver.input,
        cells,
        warning: this.solver.warningKey ? t(this.solver.warningKey, this.solver.warningVars) : '',
        difficulty: trace.solved ? i18n.difficultyName(trace.difficulty) : '—',
        clues: String(this.solver.sourcePuzzle.split('').filter((ch) => ch >= '1' && ch <= '9').length),
        technique,
        tier,
        explanation,
        counter: atFinal ? t('solver.final') : t('solver.stepOf', { i: index + 1, n }),
        steps,
        counts,
        index,
        max: n,
        canPrev: index > 0,
        canNext: index < n,
        autoplay: this.solver.autoplay,
        solvedChip: trace.solved ? t('solver.logicSolvable') : '',
        idle: false,
      }),
    });
  },

  // ------------------------------------------------------------------------
  // Photo / camera OCR
  // ------------------------------------------------------------------------
  openOcr() {
    const data = this.data.io;
    this.setData({
      io: Object.assign({}, data, { visible: false }),
      ocr: { visible: true, busy: false, error: '', errorKey: '', preview: '', status: '', progress: 0 },
    });
    this.ocrPath = '';
    this.ocrRun = (this.ocrRun || 0) + 1;
  },

  closeOcr() {
    this.ocrRun = (this.ocrRun || 0) + 1;
    this.setData({ ocr: Object.assign({}, this.data.ocr, { visible: false, busy: false }) });
  },

  chooseOcrCamera() { this.chooseOcr('camera'); },
  chooseOcrAlbum() { this.chooseOcr('album'); },

  chooseOcr(sourceType) {
    if (this.data.ocr.busy) return;
    const handle = (path) => {
      if (!path) return;
      this.ocrPath = path;
      this.setData({
        ocr: Object.assign({}, this.data.ocr, {
          preview: path, error: '', busy: true,
          status: t('ocr.loading'), progress: 2,
        }),
      });
      this.recognizeOcr(path);
    };
    if (!wx.chooseMedia) {
      // Older base libraries: chooseImage has the same camera/album sources.
      wx.chooseImage({
        count: 1,
        sourceType: [sourceType],
        sizeType: ['original', 'compressed'],
        success: (result) => handle(result.tempFilePaths && result.tempFilePaths[0]),
        fail: () => this.setData({ ocr: Object.assign({}, this.data.ocr, { busy: false }) }),
      });
      return;
    }
    wx.chooseMedia({
      count: 1,
      mediaType: ['image'],
      sourceType: [sourceType],
      camera: 'back',
      success: (result) => {
        const file = result.tempFiles && result.tempFiles[0];
        handle(file && file.tempFilePath);
      },
      fail: () => {
        this.setData({ ocr: Object.assign({}, this.data.ocr, { busy: false }) });
      },
    });
  },

  retryOcr() {
    if (this.data.ocr.busy || !this.ocrPath) return;
    this.setData({ ocr: Object.assign({}, this.data.ocr, { busy: true, error: '', status: t('ocr.loading'), progress: 2 }) });
    this.recognizeOcr(this.ocrPath);
  },

  setOcrError(key) {
    this.setData({ ocr: Object.assign({}, this.data.ocr, { busy: false, error: t(key), errorKey: key, status: '', progress: 0 }) });
  },

  recognizeOcr(path) {
    const run = (this.ocrRun || 0) + 1;
    this.ocrRun = run;
    wx.getImageInfo({
      src: path,
      success: (info) => {
        try {
          const maxSide = 1200;
          const scale = Math.min(1, maxSide / Math.max(info.width, info.height));
          const width = Math.max(1, Math.round(info.width * scale));
          const height = Math.max(1, Math.round(info.height * scale));
          const canvas = wx.createOffscreenCanvas({ type: '2d', width, height });
          const context = canvas.getContext('2d');
          const image = canvas.createImage();
          image.onload = () => {
            if (run !== this.ocrRun) return;
            try {
              context.drawImage(image, 0, 0, width, height);
              const pixels = context.getImageData(0, 0, width, height);
              this.setData({ ocr: Object.assign({}, this.data.ocr, { status: t('ocr.recognizing'), progress: 10 }) });
              ocrCore.recognizeImage(pixels, {
                recognize: async (composite) => ocrClassifier.recognizeComposite(composite, composite),
              }, {
                margins: [0.18, 0.24],
                onProgress: (progress) => {
                  if (run !== this.ocrRun) return;
                  this.setData({
                    ocr: Object.assign({}, this.data.ocr, {
                      status: t('ocr.recognizing'),
                      progress: Math.min(96, Math.round((progress.progress || 0) * 100)),
                    }),
                  });
                },
              }).then((result) => {
                if (run !== this.ocrRun) return;
                if (!result.ok) {
                  const keys = {
                    noGrid: 'ocr.failed.noGrid',
                    conflict: 'ocr.failed.invalid',
                    invalid: 'ocr.failed.invalid',
                    tooFew: 'ocr.failed.unclear',
                    noDigits: 'ocr.failed.unclear',
                    engine: 'ocr.failed.engine',
                  };
                  this.setOcrError(keys[result.reason] || 'ocr.failed.engine');
                  return;
                }
                const analysis = constructor.analyze(result.puzzle, { rate: true });
                if (analysis.status === 'invalid') return this.setOcrError('ocr.failed.unclear');
                if (analysis.status === 'conflict') return this.setOcrError('ocr.failed.invalid');
                if (analysis.status === 'none') return this.setOcrError('ocr.failed.unsolvable');
                if (analysis.status === 'multiple') return this.setOcrError('play.import.multiple');
                const meta = {
                  difficulty: analysis.rating ? analysis.rating.difficulty : 'medium',
                  maxTier: analysis.rating ? analysis.rating.maxTier : 0,
                  technique: hardestTechnique(analysis.rating),
                  clueCount: analysis.values.filter(Boolean).length,
                  source: 'ocr',
                  confidence: result.confidence,
                };
                this.ocrRun++;
                this.setData({ ocr: Object.assign({}, this.data.ocr, { visible: false, busy: false }) });
                this.loadGame(core.toPuzzleString(analysis.values), core.toPuzzleString(analysis.solution), meta);
                wx.showToast({
                  title: t(result.lowConfidence && result.lowConfidence.length ? 'ocr.successVerify' : 'ocr.success'),
                  icon: 'none',
                });
              }).catch(() => this.setOcrError('ocr.failed.engine'));
            } catch (error) {
              this.setOcrError('ocr.failed.unclear');
            }
          };
          image.onerror = () => this.setOcrError('ocr.failed.unclear');
          image.src = info.path || path;
        } catch (error) {
          this.setOcrError('ocr.failed.unclear');
        }
      },
      fail: () => this.setOcrError('ocr.failed.unclear'),
    });
  },

  // ------------------------------------------------------------------------
  // Import / export
  // ------------------------------------------------------------------------
  openIO(event) {
    const mode = event.currentTarget.dataset.mode || 'play';
    this.ioMode = mode;
    let text = '';
    if (mode === 'constructor') text = core.toPuzzleString(this.con.values);
    else if (this.play.meta) text = core.toPuzzleString(this.play.values);
    this.ioText = text;
    this.setData({ io: { visible: true, text, mode, error: '' } });
  },

  closeIO() {
    this.setData({ io: Object.assign({}, this.data.io, { visible: false, error: '' }) });
  },

  onIoInput(event) {
    this.ioText = event.detail.value;
  },

  setIoError(message) {
    this.setData({ io: Object.assign({}, this.data.io, { error: message }) });
  },

  pasteIO() {
    wx.getClipboardData({
      success: (result) => {
        this.ioText = result.data || '';
        this.setData({ io: Object.assign({}, this.data.io, { text: this.ioText, error: '' }) });
      },
      fail: () => this.setIoError(t('import.manual')),
    });
  },

  copyIO(event) {
    const kind = event.currentTarget.dataset.kind;
    let text = '';
    if (kind === 'puzzle') text = this.ioMode === 'constructor' ? core.toPuzzleString(this.con.values) : (this.play.meta ? this.play.meta.puzzleString : '');
    else if (kind === 'current') text = this.ioMode === 'constructor' ? core.toPuzzleString(this.con.values) : core.toPuzzleString(this.play.values);
    else if (kind === 'solution') text = this.play.solution ? core.toPuzzleString(this.play.solution) : '';
    if (!text) {
      wx.showToast({ title: t('import.empty'), icon: 'none' });
      return;
    }
    wx.setClipboardData({ data: text, success: () => wx.showToast({ title: t('common.copied'), icon: 'none' }) });
  },

  importIO() {
    const text = this.ioText || '';
    if (this.ioMode === 'constructor') {
      try {
        const values = core.parse(text);
        this.con.values = values.slice();
        this.con.notes = EMPTY_NOTES();
        this.con.analysis = null;
        this.con.selected = this.con.values.findIndex((value) => !value);
        if (this.con.selected < 0) this.con.selected = 40;
        this.closeIO();
        this.scheduleConAnalysis();
        wx.showToast({ title: t('constructor.imported'), icon: 'none' });
      } catch (error) {
        this.setIoError(t('play.import.invalid'));
      }
      return;
    }
    const analysis = constructor.analyze(text, { rate: true });
    if (analysis.status === 'invalid') return this.setIoError(t('play.import.invalid'));
    if (analysis.status === 'conflict') return this.setIoError(t('play.import.conflict'));
    if (analysis.status === 'none') return this.setIoError(t('play.import.none'));
    if (analysis.status === 'multiple') return this.setIoError(t('play.import.multiple'));
    const meta = {
      difficulty: analysis.rating ? analysis.rating.difficulty : null,
      maxTier: analysis.rating ? analysis.rating.maxTier : 0,
      technique: hardestTechnique(analysis.rating),
      clueCount: analysis.values.filter(Boolean).length,
      source: 'imported',
    };
    this.loadGame(core.toPuzzleString(analysis.values), core.toPuzzleString(analysis.solution), meta);
    this.closeIO();
    wx.showToast({ title: t('play.import.success'), icon: 'none' });
  },
});
